        if isinstance(val, str):
            val = val.replace(',', '.')
            return float(val)
        return float(val)

    a_val = parse_value(a)
    b_val = parse_value(b)

    if a_val == b_val:
        return None
    elif a_val > b_val:
        return a
    else:
        return b

